import fs from'node:fs';
test('D090 finite ten slots retain seven1200 and three1800 caps without relaxing any older frame budget',()=>{const scope=JSON.parse(fs.readFileSync('proposals/d090/scope.json'));assert.equal(scope.models.length,10);assert.equal(scope.models.filter(m=>m.size===1&&m.cap===1200).length,7);assert.equal(scope.models.filter(m=>m.size===2&&m.cap===1800).length,3);for(const m of scope.models){const slot=m.k+':'+m.v,caps={[slot]:m.cap},before={whole:100},row={slot,before:20,after:m.cap};assertLedger(before,{whole:80+m.cap},[row],caps);assert.throws(()=>assertLedger(before,{whole:81+m.cap},[{...row,after:m.cap+1}],caps));assert.throws(()=>assertLedger(before,{whole:80+m.cap},[row],{}));}});
